var EXTRA=[{dot:"green",j:"Arthroscopy Techniques",h:"Un tunnel femorale unico per ricostruire insieme LCA e angolo postero-laterale",v:"Nota tecnica brasiliana: retto femorale e semitendinoso condividono un solo tunnel femorale per ricostruire insieme il legamento crociato anteriore e l'angolo postero-laterale, con l'obiettivo di ridurre il rischio di convergenza dei tunnel.",pmid:'42799422',doi:'10.1002/atn2.70275',temi:["multilegamentose","angolo postero-laterale"]},{dot:"gray",j:"Arthroscopy",h:"Il trapianto di menisco da allograft funziona bene negli atleti, ma con complicanze frequenti",v:"Revisione sistematica di 13 studi, oltre mille pazienti: funzione, dolore e rientro allo sport migliorano nettamente dopo trapianto di menisco da allograft, a fronte però di tassi di complicanza e revisione non trascurabili.",pmid:'42791500',doi:'10.1002/arj.70592',temi:["menisco","trapianto allograft"]},{dot:"gray",j:"BMC Musculoskeletal Disorders",h:"A 11 anni, il release del retinacolo laterale con cartilagine tiene nell'artrosi rotulea isolata",v:"Studio cinese retrospettivo con l'orizzonte più lungo visto finora su questa procedura: il release artroscopico del retinacolo laterale combinato a un intervento sulla cartilagine mantiene il miglioramento funzionale in pazienti selezionati con artrosi femoro-rotulea isolata.",pmid:'42786458',doi:'10.1186/s12891-026-10358-2',temi:["rotula","cartilagine"]},{dot:"gray",j:"Bioengineering",h:"L'intelligenza artificiale in protesica è ancora poco validata fuori dal laboratorio",v:"Mappa strutturata di 252 pubblicazioni sull'intelligenza artificiale in artroplastica: solo una minoranza supera una vera validazione esterna, e gran parte dell'evidenza resta interna al centro che ha sviluppato il modello.",pmid:'42791908',doi:'10.3390/bioengineering13091036',temi:["intelligenza artificiale","protesi"]},{dot:"gray",j:"Bioengineering",h:"Le classificazioni del menisco discoide passano dalla forma alla funzione",v:"Rassegna sull'evoluzione dei sistemi di classificazione del menisco discoide, dalla morfologia di Watanabe fino al sistema PRiSM, che integra stabilità del margine periferico e caratteristiche della lesione.",pmid:'42791935',doi:'10.3390/bioengineering13091063',temi:["menisco discoide","classificazione"]},{dot:"gray",j:"Journal of Clinical Medicine",h:"Un nodo di sutura evita la rimozione dell'impianto nelle fratture del polo rotuleo",v:"Studio cinese retrospettivo: la fissazione con nodo di sutura multi-filamento e ancora, rispetto al tradizionale filo di Kirschner a banda di tensione, azzera la necessità di rimuovere l'impianto nelle fratture del polo inferiore della rotula, a parità di esito funzionale.",pmid:'42795786',doi:'10.3390/jcm15187014',temi:["rotula","fissazione"]},{dot:"gray",j:"Journal of ISAKOS",h:"Un indice clinico-radiologico per riconoscere il menisco laterale ipermobile prima dell'artroscopia",v:"Modello diagnostico argentino-ecuadoriano che integra sintomi clinici e risonanza magnetica per predire, prima dell'artroscopia, l'ipermobilità del menisco laterale confermata poi dinamicamente in sala operatoria.",pmid:'42800675',doi:'10.1016/j.jisako.2026.101227',temi:["menisco laterale","diagnostica"]},{dot:"gray",j:"The Journal of Knee Surgery",h:"Il prelievo del peroneo lungo per il LCA non richiede sempre la tenodesi peroneale",v:"Studio randomizzato indiano su innesto di peroneo lungo per il LCA — innesto che tu non usi —: la tenodesi peroneale di routine dopo il prelievo non mostra un vantaggio funzionale rispetto a non eseguirla.",pmid:'42790534',doi:'10.1055/a-2968-6212',temi:["innesto alternativo","LCA"]},{dot:"gray",j:"Bioengineering",h:"La prontezza psicologica al rientro segue la percezione del paziente, non il test di equilibrio",v:"Studio trasversale su quaranta pazienti dopo LCA: la prontezza psicologica al rientro allo sport si lega molto più alla funzione percepita dal paziente che alla prestazione oggettiva al test di equilibrio a stella.",pmid:'42791900',doi:'10.3390/bioengineering13091028',temi:["ritorno allo sport","aspetti psicologici"]},{dot:"gray",j:"The Knee",h:"L'osteotomia della tuberosità tibiale si può ripetere in sicurezza nella re-revisione protesica",v:"Serie inglese su decine di osteotomie sequenziali della tuberosità tibiale come via d'accesso nella chirurgia di re-revisione protesica del ginocchio: la guarigione ossea resta affidabile anche alla seconda osteotomia sullo stesso ginocchio.",pmid:'42790394',doi:'10.1016/j.knee.2026.104643',temi:["protesi","revisione"]},{dot:"gray",j:"Journal of Experimental Orthopaedics",h:"Associare plasma ricco di piastrine e acido ialuronico batte l'acido ialuronico da solo",v:"Studio greco prospettico comparativo: la combinazione di plasma ricco di piastrine e acido ialuronico ad alto peso molecolare migliora di più dolore, funzione e qualità di vita nell'artrosi di ginocchio rispetto al solo acido ialuronico — un tassello in più sul tema del PICK di ieri.",pmid:'42788068',doi:'10.1002/jeo2.70909',temi:["PRP","acido ialuronico"]},{dot:"gray",j:"Medicina",h:"Bottone corticale o vite più graffa a U: due fissazioni tibiali a confronto nel LCA",v:"Coorte retrospettiva turca su innesto di hamstring: nessuna delle due fissazioni tibiali si dimostra costantemente superiore su stabilità clinica e fallimento dell'innesto, con vantaggi diversi e minori su dolore del sito donatore e punteggio funzionale.",pmid:'42796236',doi:'10.3390/medicina62091629',temi:["LCA","fissazione tibiale"]}];
var SCOPERTE=[{t:"Un progetto di popolazione giapponese cerca nell'alimentazione i segnali nascosti dell'artrosi",v:"Un programma di promozione della salute nella prefettura di Aomori applica apprendimento automatico e reti bayesiane a quasi mille variabili cliniche, di laboratorio e alimentari su 703 residenti, per cercare fattori associati all'artrosi radiografica di ginocchio oltre ai soliti sospetti (età, sesso, peso). Vale la deviazione perché è esattamente l'incrocio che ti interessa — intelligenza artificiale applicata alla medicina, stavolta su una popolazione e abitudini alimentari che raramente compaiono nella letteratura occidentale sul ginocchio.",pmid:'42787146',doi:'10.1016/j.ocarto.2026.100874',temi:["intelligenza artificiale","mondo orientale"]},{t:"Dalla cartilagine dell'orecchio nasce una cornea trasparente",v:"Un gruppo dell'Università di Zhejiang trasforma cartilagine auricolare autologa, trattata con un processo alcalino, in un innesto trasparente per la ricostruzione della cornea, con proprietà ottiche e meccaniche vicine a quelle dello stroma corneale nativo e buona integrazione in un modello animale. Vale la deviazione perché rovescia la direzione consueta dell'ingegneria tissutale della cartilagine — non ricostruire il ginocchio da un altro tessuto, ma usare la cartilagine per ricostruire un organo completamente diverso.",pmid:'42800427',doi:'10.1016/j.biomaterials.2026.124644',temi:["bioingegneria","cartilagine"]},{t:"Un'impalcatura di cartilagine che cambia forma a contatto con i liquidi articolari",v:"Un gruppo cinese sviluppa un'impalcatura porosa a memoria di forma, rinforzata da nanofibre a doppio strato che rilasciano in modo prolungato una molecola pro-condrogenica, e che si adatta al profilo del difetto cartilagineo quando si idrata. Vale la deviazione perché è un tassello di bioingegneria dei materiali — non farmacologia né chirurgia — sulla stessa domanda che segui nella cartilagine: far sì che il materiale, non solo la tecnica, aiuti la rigenerazione.",pmid:'42801603',doi:'10.1002/advs.77845',temi:["bioingegneria","cartilagine"]}];
var SOC={"1": {"video": "Oggi parliamo di che cosa succede quando bisogna rifare l'intervento di ricostruzione del legamento crociato anteriore, dopo che il primo tentativo e' fallito. Uno studio su trecento pazienti, operati in tre centri specializzati fra Argentina ed Ecuador, ha confrontato la revisione da sola con la revisione a cui viene aggiunto un piccolo rinforzo sul lato esterno del ginocchio. Il risultato: a cinque anni di distanza, il nuovo legamento tiene nel novanta virgola sei per cento dei casi con il rinforzo, contro il settantanove virgola nove per cento senza. Anche l'instabilita' rotatoria residua si riduce di molto. Il punto onesto: lo studio non e' randomizzato, quindi non possiamo dire con assoluta certezza che sia proprio il rinforzo a fare la differenza, e non sappiamo quale delle due tecniche di rinforzo funzioni meglio dell'altra. Resta pero' un segnale importante, in una situazione — la revisione del crociato — dove ogni margine di sicurezza in piu' conta davvero.","linkedin": "Coorte multicentrica retrospettiva con ponderazione per propensione (Collazo, Rivarola, Palanconi et al., Journal of ISAKOS, settembre 2026) su 300 revisioni monostadio del LCA: l'aumento laterale (LET o ricostruzione ALL, aggregati) si associa a una sopravvivenza dell'innesto a 5 anni del 90,6% contro il 79,9% della revisione isolata (HR IPTW 0,46; IC 95% 0,28-0,74; p=0,002) e a un pivot shift residuo dimezzato (17,0% contro 34,0%; p=0,001). Limite dichiarato: livello III, allocazione non randomizzata, confronto esplorativo LET-contro-ALL non conclusivo (HR 0,91; IC 95% 0,39-2,10).","instagram": "🦵 Rifare il crociato: un rinforzo laterale in più aiuta a tenere?\n\nUno studio su 300 pazienti operati una seconda volta di ricostruzione del legamento crociato anteriore mostra che aggiungere un piccolo rinforzo sul lato esterno del ginocchio riduce il rischio che il nuovo legamento ceda nei cinque anni successivi (90,6% contro 79,9% di sopravvivenza dell'innesto).\n\nIl limite: lo studio non è randomizzato, quindi non dimostra da solo la causa — ma il segnale è forte e coerente con altri dati recenti.","pazienti": "Quando il primo intervento di ricostruzione del legamento crociato anteriore non tiene e serve rifarlo, i chirurghi si chiedono spesso se aggiungere un piccolo gesto in più, un rinforzo sul lato esterno del ginocchio, aiuti a evitare un secondo cedimento.\n\nUno studio condotto in tre centri specializzati fra Argentina ed Ecuador, su trecento pazienti operati per la seconda volta, ha confrontato chi ha ricevuto solo la revisione con chi ha ricevuto anche questo rinforzo laterale. A cinque anni di distanza, il nuovo legamento teneva nel 90,6% dei casi con il rinforzo, contro il 79,9% senza.\n\nUn punto va detto con chiarezza: questo non è uno studio randomizzato, quindi non possiamo essere certi al cento per cento che sia proprio il rinforzo laterale a spiegare tutta la differenza — potrebbero avere contribuito anche altri fattori legati ai pazienti scelti per riceverlo. Resta comunque un segnale importante in una situazione, la revisione del crociato, dove ogni margine di sicurezza in più conta."}};
var SOCV={"1": {"video": {"chir": ["Coorte retrospettiva multicentrica argentino-ecuadoriana (Collazo, Rivarola, Palanconi et al., Journal of ISAKOS, settembre 2026), 300 revisioni monostadio del LCA con ponderazione IPTW: l'aumento laterale — LET o ricostruzione ALL, aggregati — si associa a una sopravvivenza dell'innesto a 5 anni del 90,6% contro il 79,9% della revisione isolata (HR 0,46; IC 95% 0,28-0,74; p=0,002).","Anche il pivot shift residuo si dimezza (17,0% contro 34,0%; OR 0,42; IC 95% 0,25-0,71; p=0,001), mentre la differenza sulla lassità strumentale (-0,21mm; p=0,015), pur significativa, è dichiarata dagli stessi autori non interpretabile clinicamente. Il confronto esplorativo diretto fra LET e ricostruzione ALL non mostra differenza (HR 0,91; IC 95% 0,39-2,10; p=0,82).","Il limite maggiore: livello III, coorte retrospettiva non randomizzata, con possibile confondimento residuo nonostante la ponderazione per propensione; il tipo di innesto della ricostruzione del LCA non è riportato come variabile isolata. Un lavoro utile, ma da leggere insieme al registro francese uscito lo stesso giorno sullo stesso tema — l'innesto non-hamstring — senza che nessuno dei due isoli ancora la combinazione esatta di innesto e rinforzo laterale."],"misto": ["Uno studio su trecento pazienti, operati in tre centri specializzati fra Argentina ed Ecuador, ha confrontato la revisione del legamento crociato anteriore da sola con la revisione a cui viene aggiunto un piccolo rinforzo sul lato esterno del ginocchio.","Il risultato: a cinque anni, il nuovo legamento tiene nel 90,6% dei casi con il rinforzo, contro il 79,9% senza; anche l'instabilità rotatoria residua si riduce nettamente.","Il punto onesto: lo studio non è randomizzato, quindi non possiamo dire con assoluta certezza che sia proprio il rinforzo a fare la differenza, e non sappiamo quale delle due tecniche di rinforzo funzioni meglio. Resta comunque un segnale importante in una situazione dove ogni margine di sicurezza in più conta davvero."],"pazienti": ["Quando bisogna rifare l'intervento di ricostruzione del legamento crociato anteriore, i chirurghi si chiedono spesso se aggiungere un piccolo rinforzo sul lato esterno del ginocchio aiuti a evitare un secondo cedimento.","Uno studio su trecento pazienti operati una seconda volta mostra che, a cinque anni di distanza, il nuovo legamento teneva nel 90,6% dei casi con il rinforzo, contro il 79,9% senza.","Un punto va detto con chiarezza: non è uno studio randomizzato, quindi non possiamo essere certi al cento per cento che sia solo il rinforzo a spiegare la differenza. Resta però un segnale importante in una situazione dove ogni margine di sicurezza in più conta."]},"linkedin": {"chir": ["Coorte retrospettiva multicentrica IPTW (Collazo, Rivarola, Palanconi et al., J ISAKOS, set 2026), 300 revisioni del LCA: l'aumento laterale (LET/ALL) porta la sopravvivenza dell'innesto a 5 anni al 90,6% contro il 79,9% della sola revisione (HR 0,46; IC 95% 0,28-0,74; p=0,002).","Pivot shift residuo dimezzato (17,0% contro 34,0%; p=0,001). Confronto esplorativo LET-contro-ALL non conclusivo (HR 0,91; IC 95% 0,39-2,10).","Limite: livello III, non randomizzato, tipo di innesto del LCA non isolato nell'abstract. Converge con un registro francese uscito lo stesso giorno a favore dell'innesto non-hamstring — nessuno dei due isola ancora la tua combinazione esatta."],"misto": ["Uno studio su 300 pazienti operati una seconda volta di ricostruzione del legamento crociato anteriore mostra che aggiungere un rinforzo sul lato esterno del ginocchio riduce il rischio di un nuovo cedimento nei cinque anni successivi.","Sopravvivenza dell'innesto a 5 anni: 90,6% con il rinforzo contro 79,9% senza.","Limite: studio non randomizzato, non isola quale delle due tecniche di rinforzo funzioni meglio."],"pazienti": ["Quando si rifà l'intervento al legamento crociato, un piccolo rinforzo in più sul lato del ginocchio aiuta a tenere.","Su 300 pazienti, il nuovo legamento teneva a 5 anni nel 90,6% dei casi con il rinforzo, contro il 79,9% senza.","Non è uno studio randomizzato: un segnale forte, non una certezza assoluta."]},"instagram": {"chir": ["🦵📊 300 revisioni del LCA: il rinforzo laterale (LET/ALL) porta la sopravvivenza dell'innesto a 5 anni al 90,6% contro il 79,9% (HR 0,46; p=0,002).","Pivot shift residuo dimezzato. LET contro ALL: confronto ancora non conclusivo.","Limite: coorte retrospettiva non randomizzata, livello III."],"misto": ["🦵 Rifare il crociato: un rinforzo laterale in più aiuta a tenere?","Su 300 pazienti, il nuovo legamento teneva a 5 anni nel 90,6% dei casi con il rinforzo, contro il 79,9% senza.","Il limite: studio non randomizzato, non dimostra da solo la causa."],"pazienti": ["🦵 Quando si rifà l'intervento al crociato, un rinforzo in più può aiutare a tenere.","Su 300 pazienti, il nuovo legamento teneva a 5 anni nel 90,6% dei casi con il rinforzo, contro il 79,9% senza.","Non è una certezza assoluta, ma un segnale importante da conoscere."]},"reel": {"chir": ["[REVISIONE DEL LCA: SERVE UN RINFORZO LATERALE?] 300 pazienti, sopravvivenza dell'innesto a 5 anni: 90,6% con rinforzo contro 79,9% senza.","[PERCHÉ] Pivot shift residuo dimezzato; confronto LET-contro-ALL ancora non conclusivo.","[IL LIMITE] Coorte retrospettiva non randomizzata, livello III."],"misto": ["[RIFARE IL CROCIATO: UN RINFORZO IN PIÙ AIUTA?] Studio su 300 pazienti operati una seconda volta.","[IL RISULTATO] Il nuovo legamento tiene di più con il rinforzo: 90,6% contro 79,9% a 5 anni.","[IL LIMITE] Studio non randomizzato: un segnale forte, non una prova definitiva."],"pazienti": ["[SI DEVE RIFARE IL CROCIATO: SERVE UN RINFORZO IN PIÙ?] Uno studio su 300 pazienti risponde.","[COSA DICE LA SCIENZA] Con il rinforzo, il nuovo legamento tiene di più: 90,6% contro 79,9% a 5 anni.","[DA SAPERE] Non è una certezza assoluta, ma un segnale importante da discutere col tuo chirurgo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #LegamentoCrociato #ChirurgiaDelGinocchio","instagram": "#ortopedia #legamentocrociato #lca #chirurgiadelginocchio #ginocchio #ortopedico #medicinasportiva #sportsmedicine #revisionelca","kw": "revisione legamento crociato, rinforzo laterale ginocchio, LET ginocchio"}};
var NLB={"1": {"prof": ["Revisione del LCA: l'aumento laterale associato a maggiore sopravvivenza dell'innesto","Uno studio multicentrico con ponderazione per propensione su 300 revisioni del legamento crociato anteriore mostra che aggiungere un gesto laterale (tenodesi extra-articolare o ricostruzione del legamento antero-laterale) si associa a una sopravvivenza dell'innesto a 5 anni del 90,6% contro il 79,9% della sola revisione (HR 0,46; IC 95% 0,28-0,74).","Nota critica: studio retrospettivo non randomizzato, il confronto diretto fra le due tecniche di aumento laterale non è conclusivo e il tipo di innesto della ricostruzione non è specificato."],"mix": ["Nella revisione del legamento crociato, un gesto in più sul lato del ginocchio riduce i nuovi cedimenti","Uno studio su 300 pazienti operati per la seconda volta di ricostruzione del legamento crociato anteriore mostra che aggiungere un rinforzo sul lato esterno del ginocchio, oltre alla sola ricostruzione, riduce il rischio di un nuovo cedimento dell'innesto nei cinque anni successivi.","Nota sul limite: lo studio non è randomizzato, quindi non può escludere che altri fattori, e non solo il rinforzo laterale, spieghino parte del vantaggio osservato."],"paz": ["Quando si rioperano crociati già ricostruiti, un rinforzo in più aiuta a tenere","In chi deve rifare l'intervento di ricostruzione del legamento crociato anteriore, uno studio su 300 pazienti mostra che aggiungere un piccolo rinforzo sul lato esterno del ginocchio si associa a un rischio più basso che il nuovo legamento ceda nei cinque anni successivi.","È un'osservazione su pazienti già operati una volta, non uno studio randomizzato: non dimostra da sola che il rinforzo sia la causa del miglior risultato, ma va nella stessa direzione di altri studi recenti."],"kw": "revisione legamento crociato, rinforzo laterale ginocchio, tenodesi laterale"},"2": {"prof": ["Simmetria del quadricipite a 12 mesi dalla ricostruzione del LCA: predittore di rirottura a 24 mesi","In una coorte di 48 atleti, un indice di simmetria del quadricipite (LSI) sotto l'85% a fine primo anno si associa a un rischio di rirottura ipsilaterale entro 24 mesi triplicato (RR 3,21; IC 95% 1,17-8,82), mentre lassità strumentale e hop test non mostrano un'associazione robusta.","Nota critica: la precedenza temporale fra la misura di LSI e la rirottura non è stabilita per limiti dichiarati del disegno dei dati, e la soglia dell'85% è esplorativa, non validata."],"mix": ["La forza del quadricipite conta più del salto nel prevedere un nuovo cedimento del crociato","In un gruppo di 48 atleti operati di ricostruzione del legamento crociato anteriore, chi aveva una forza del quadricipite più asimmetrica a un anno dall'intervento ha avuto, nei due anni successivi, più cedimenti del nuovo legamento — un segnale più chiaro di quello dato dal test del salto o dalla lassità misurata in ambulatorio.","Nota sul limite: lo studio non può stabilire con certezza se la debolezza del quadricipite preceda il cedimento o ne sia in parte conseguenza, e il campione è piccolo."],"paz": ["La forza della coscia dopo l'intervento al crociato può avvertire in anticipo","Uno studio su 48 giovani sportivi operati di legamento crociato anteriore suggerisce che una forza del muscolo della coscia ancora molto disuguale rispetto alla gamba sana, a un anno dall'intervento, si accompagna più spesso a un nuovo cedimento del legamento nei due anni successivi.","È un'osservazione preliminare su un piccolo gruppo di pazienti, non una regola valida per tutti: serve comunque a ricordare che tornare allo sport richiede più della sola sensazione di stare bene."],"kw": "rirottura legamento crociato, forza quadricipite dopo LCA, ritorno allo sport"},"3": {"prof": ["Lesioni combinate LCA-collaterale mediale: l'innesto non-hamstring resta favorito","Un registro prospettico multicentrico francese su 489 pazienti mostra che gli innesti diversi dall'hamstring si associano a punteggi IKDC più alti (β=7,89; IC 95% 3,45-12,33), indipendentemente dallo stato del legamento collaterale mediale, trattato o meno chirurgicamente.","Nota critica: livello III, coorte di registro non randomizzata; la categoria «non-hamstring» aggrega innesti diversi senza distinguere il tendine quadricipitale dagli altri."],"mix": ["Anche quando è coinvolto il legamento interno, l'innesto scelto per il crociato conta","Un registro francese su quasi 500 pazienti con lesione del legamento crociato anteriore, isolata o combinata con quella del legamento collaterale mediale, mostra che scegliere un innesto diverso dagli ischiocrurali per ricostruire il crociato si associa a punteggi funzionali migliori, anche quando il legamento interno è coinvolto.","Nota sul limite: lo studio non è randomizzato e non distingue, fra gli innesti «non ischiocrurali», quale in particolare dia il vantaggio maggiore."],"paz": ["Anche con un legamento interno danneggiato, la scelta dell'innesto per il crociato conta","In un registro francese su quasi 500 pazienti operati di legamento crociato anteriore, chi è stato ricostruito con un innesto diverso dal tendine degli ischiocrurali ha avuto, in media, un recupero funzionale migliore — anche quando era danneggiato anche il legamento sul lato interno del ginocchio.","È un'osservazione di registro, non uno studio randomizzato: indica un'associazione, non dimostra da sola che l'innesto scelto sia l'unica causa della differenza osservata."],"kw": "innesto legamento crociato, ricostruzione LCA collaterale mediale, chirurgia ginocchio"},"4": {"prof": ["In revisione del LCA, più differisce lo slope tibiale mediale-laterale, peggio va l'esito","In 31 revisioni del legamento crociato anteriore, un maggiore slope tibiale posteriore differenziale (mediale contro laterale) si correla con un minor miglioramento del KOOS Dolore (p<0,001), Sport e tempo libero (p=0,034) e Qualità di vita (p=0,010) a un anno.","Nota critica: coorte retrospettiva monocentrica di 31 pazienti, correlazione senza aggiustamento per i confondenti abituali (età, innesto, lesioni associate)."],"mix": ["Nella revisione del crociato, la forma dell'osso tibiale può pesare sul risultato","Uno studio inglese su 31 pazienti sottoposti a un secondo intervento di ricostruzione del legamento crociato anteriore mostra che una maggiore differenza di inclinazione fra il lato interno e il lato esterno della parte superiore della tibia si associa a un recupero di dolore e qualità di vita meno soddisfacente.","Nota sul limite: è un'osservazione su un numero piccolo di pazienti, che mostra un'associazione ma non prova che correggere quella inclinazione cambi il risultato."],"paz": ["Nella revisione del crociato, la forma dell'osso può influenzare il recupero","In 31 pazienti operati una seconda volta di ricostruzione del legamento crociato anteriore, chi aveva una maggiore differenza nell'inclinazione ossea fra il lato interno ed esterno del ginocchio ha avuto, in media, un recupero di dolore e qualità di vita meno soddisfacente a un anno.","Sono numeri piccoli, da confermare su più pazienti: indicano una direzione, non una regola per ogni caso."],"kw": "revisione legamento crociato, slope tibiale, chirurgia ginocchio"},"5": {"prof": ["Radice del menisco laterale con LCA: stesso esito a 4 anni fra lesione radiale e avulsione","In 65 pazienti operati di ricostruzione del LCA con riparazione della radice del menisco laterale, IKDC, valore soggettivo del ginocchio e Tegner non differiscono a un follow-up medio di 51 mesi fra lesioni radiali (n=34) e da avulsione (n=31); il livello di rientro allo sport differisce (p=0,026), a favore delle lesioni radiali.","Nota critica: livello III, retrospettivo, assenza di imaging postoperatorio oggettivo, campione limitato per il confronto sul livello di rientro allo sport."],"mix": ["Nella radice del menisco laterale associata al crociato, il tipo di lesione non cambia molto l'esito","Uno studio francese su 65 pazienti operati insieme di legamento crociato anteriore e radice del menisco esterno mostra che, a oltre quattro anni, il tipo di lesione (uno strappo o un distacco netto) non cambia in modo sostanziale il recupero funzionale, anche se sembra influenzare a che livello sportivo si torna.","Nota sul limite: mancano controlli con risonanza dopo l'intervento, e il confronto sul livello di rientro sportivo va preso con cautela per il campione limitato."],"paz": ["Radice del menisco esterno lesa insieme al crociato: il tipo di lesione conta poco sul recupero","In 65 pazienti operati insieme di legamento crociato anteriore e di una lesione della radice del menisco esterno, il tipo preciso di lesione meniscale non ha cambiato in modo sostanziale il recupero funzionale a oltre quattro anni dall'intervento.","È uno studio retrospettivo su un numero limitato di pazienti: dà un'indicazione utile, non una certezza definitiva."],"kw": "radice menisco laterale, legamento crociato anteriore, chirurgia menisco"},"6": {"prof": ["Retto femorale isolato per il LCA: la prima revisione narrativa dedicata","Una revisione narrativa secondo i criteri SANRA sintetizza l'evidenza anatomica, biomeccanica e clinica — ancora limitata a tre sole serie — sull'innesto isolato di tendine del retto femorale per la ricostruzione del LCA, descrivendo proprietà biomeccaniche favorevoli e risultati clinici a breve termine promettenti.","Nota critica: revisione narrativa non sistematica, nessun dato numerico di esito riportato nell'abstract, evidenza clinica ancora minima."],"mix": ["Il tendine usato più spesso da chi legge questo briefing ha ora una prima rassegna dedicata","Una rassegna della letteratura fa il punto su un innesto per la ricostruzione del legamento crociato anteriore che preleva solo la parte superficiale del tendine del quadricipite (il retto femorale), invece del tendine intero: le prime indicazioni biomeccaniche e cliniche sono incoraggianti, ma restano ancora poche.","Nota sul limite: non è una revisione sistematica, e i dati clinici disponibili sono limitati a tre sole serie di pazienti."],"paz": ["Un innesto meno invasivo per ricostruire il legamento del ginocchio: primo bilancio della letteratura","Una rassegna scientifica riassume quanto si sa oggi su una variante dell'innesto di tendine del quadricipite, che preleva solo una sua parte superficiale, per ricostruire il legamento crociato anteriore del ginocchio: i primi segnali sono incoraggianti su forza e recupero.","I dati clinici disponibili sono ancora pochi: serve altro tempo e altri studi prima di trarre conclusioni definitive."],"kw": "innesto retto femorale, ricostruzione LCA, tendine quadricipite"},"7": {"prof": ["Un profilo RM multidimensionale distingue il LCA infortunato in età pediatrica","In 462 RM di ginocchio in pazienti ≤18 anni, 13 di 18 parametri morfometrici femoro-tibiali differiscono significativamente fra lesione del LCA e controlli; i modelli di apprendimento automatico raggiungono un'AUC fino a 0,959 (IC 95% 0,905-0,992) nel classificare la lesione già accertata.","Nota critica: caso-controllo retrospettivo monocentrico senza validazione esterna; i modelli classificano una lesione avvenuta, non predicono il rischio futuro, come dichiarano gli stessi autori."],"mix": ["La forma dell'osso del ginocchio nei più giovani si lega alla rottura del crociato","Uno studio turco su 462 risonanze di ginocchio in ragazzi e ragazze fino a 18 anni mostra che, fra chi ha rotto il legamento crociato anteriore e chi no, la forma dell'osso del femore e della tibia differisce in modo misurabile e riconoscibile da un modello computerizzato con alta accuratezza.","Nota sul limite: lo studio guarda indietro nel tempo, su una lesione già avvenuta — non dice ancora se questi tratti anatomici possano prevedere il rischio futuro in un ragazzo che non si è ancora infortunato."],"paz": ["Nei più giovani, la forma dell'osso del ginocchio può dire qualcosa sul crociato","In uno studio su oltre 450 risonanze di ginocchio in bambini e ragazzi, la forma di alcune parti dell'osso del femore e della tibia è risultata diversa fra chi aveva rotto il legamento crociato anteriore e chi no.","È uno studio che guarda a lesioni già avvenute, non uno strumento pronto per prevedere chi si farà male: serve ancora conferma su altri gruppi di pazienti."],"kw": "LCA adolescente, lesione crociato bambini, risonanza ginocchio"},"8": {"prof": ["A 24 mesi l'asimmetria eccentrica degli hamstring si dimezza, ma resta in 1 su 4","Confronto trasversale fra due coorti indipendenti di 30 atleti dopo ricostruzione del LCA con hamstring: LSI della forza eccentrica di picco 84,6±9,3% a 12 mesi contro 93,5±6,8% a 24 mesi (p<0,001), ma il 23,3% resta sotto il 90% anche a 24 mesi.","Nota critica: disegno trasversale fra coorti diverse, non longitudinale; monocentrico, solo atleti maschi, innesto di hamstring."],"mix": ["Anche a due anni dall'intervento, la forza dei muscoli posteriori della coscia non è sempre tornata simmetrica","Uno studio confronta due gruppi indipendenti di atleti, uno valutato a un anno e uno a due anni dalla ricostruzione del legamento crociato anteriore: l'asimmetria di forza dei muscoli posteriori della coscia si riduce nettamente col tempo, ma quasi un atleta su quattro resta sotto la soglia di normalità anche a due anni.","Nota sul limite: i due gruppi sono persone diverse valutate una sola volta, non gli stessi atleti seguiti nel tempo, e riguarda un innesto diverso da quello che usi tu."],"paz": ["Dopo due anni, la forza della coscia non è sempre tornata del tutto uguale","Uno studio su atleti operati di legamento crociato anteriore mostra che la forza dei muscoli posteriori della coscia diventa più simmetrica col passare del tempo, ma anche a due anni dall'intervento una parte degli atleti non ha ancora recuperato una forza pienamente equivalente fra le due gambe.","Riguarda un innesto diverso da quello più usato in questo studio di caso specifico, ma il messaggio di fondo — il tempo da solo non basta a garantire un recupero completo — vale in generale."],"kw": "forza hamstring dopo LCA, ritorno allo sport ginocchio, riabilitazione crociato"},"9": {"prof": ["Fratture periprotesiche di ginocchio: successo terapeutico nell'81% dei casi in una casistica bicentrica","In 56 pazienti trattati per frattura periprotesica dopo protesi totale di ginocchio, il 91% è stato trattato chirurgicamente (revisione protesica o osteosintesi) con un successo terapeutico dell'81%; nella revisione, la sostituzione della componente femorale con impianto semi-vincolato è stata la scelta più frequente.","Nota critica: studio retrospettivo bicentrico non comparativo, campione piccolo, criteri di successo non dettagliati numericamente oltre la percentuale complessiva."],"mix": ["Le fratture attorno a una protesi di ginocchio si possono trattare con buoni risultati","Uno studio polacco su 56 pazienti con frattura ossea attorno a una protesi di ginocchio già impiantata mostra che, nella maggior parte dei casi, un trattamento chirurgico mirato — con osteosintesi se la protesi resta stabile, o con la sostituzione di una sua parte se non lo è — porta a un buon risultato.","Nota sul limite: è uno studio retrospettivo su un numero limitato di pazienti, senza un confronto diretto fra le diverse strategie di trattamento."],"paz": ["Una frattura vicino a una protesi di ginocchio si può curare, con l'intervento giusto","A volte, attorno a una protesi di ginocchio già impiantata, può verificarsi una frattura dell'osso. Uno studio su 56 pazienti mostra che, nella grande maggioranza dei casi, un intervento chirurgico mirato porta a un buon risultato, con un tasso di successo dell'81%.","È un'osservazione retrospettiva su un numero limitato di pazienti: dà comunque un quadro rassicurante su una complicanza possibile ma trattabile."],"kw": "frattura periprotesica ginocchio, protesi ginocchio complicanze, revisione protesi"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Il rinforzo laterale migliora la sopravvivenza dell'innesto in revisione",v:"Coorte multicentrica con ponderazione per propensione, 300 revisioni del LCA: l'aumento laterale (LET o ALL) dimezza quasi il fallimento dell'innesto rispetto alla sola revisione.",ax:"Collazo, Rivarola, Palanconi, Meninato, Peñaherrera-Carrillo, Barros Castro, Endara Urresta",date:"set 2026",meta:"coorte retrospettiva multicentrica, IPTW, 300 pazienti, follow-up 5,8 anni · [III]",pmid:'42800674',doi:'10.1016/j.jisako.2026.101224',journal:"Journal of ISAKOS : joint disorders & orthopaedic sports medicine",authors:"Collazo C, Rivarola H, Palanconi M, Meninato M, Peñaherrera-Carrillo C, Barros Castro A, Endara Urresta F",design:"Studio di coorte retrospettivo multicentrico (tre centri ad alto volume) su pazienti sottoposti a revisione monostadio del LCA per la prima volta; confronto fra revisione isolata e revisione con aumento laterale (tenodesi extra-articolare laterale, LET, o ricostruzione del legamento antero-laterale, ALL, aggregati nell'analisi primaria); ponderazione con probabilità inversa di trattamento (IPTW) su punteggio di propensione; esito primario il fallimento dell'innesto; confronto esplorativo LET-contro-ALL dichiarato non conclusivo dagli stessi autori.",pop:"300 pazienti su 364 screenati (64 esclusi): 100 revisioni isolate, 100 con LET, 100 con ricostruzione ALL; follow-up medio 5,8±1,1 anni.",results:"Fallimento dell'innesto: 20,0% (20/100) nella revisione isolata contro 9,5% (19/200) con aumento laterale; sopravvivenza pesata a 5 anni 79,9% contro 90,6% (HR aggiustato IPTW 0,46; IC 95% 0,28-0,74; p=0,002). Pivot shift residuo: 34,0% contro 17,0% (OR pesato 0,42; IC 95% 0,25-0,71; p=0,001). Lassità anteriore strumentale: 2,60±1,00 mm contro 2,25±0,85 mm (differenza -0,21 mm; IC 95% -0,38/-0,04; p=0,015, non ritenuta clinicamente interpretabile dagli autori). Confronto esplorativo LET contro ALL: nessuna differenza significativa sul fallimento dell'innesto (HR 0,91; IC 95% 0,39-2,10; p=0,82) — non interpretabile come equivalenza.",concl:"Gli autori concludono che l'aumento laterale si associa a maggiore sopravvivenza dell'innesto e minore lassità rotatoria residua dopo revisione del LCA, ma sottolineano che l'allocazione non randomizzata impedisce di stabilire un nesso causale, e che il confronto diretto fra LET e ALL non dimostra equivalenza.",limits:"Livello III, coorte retrospettiva non randomizzata: possibile confondimento residuo nonostante l'IPTW · tipo di innesto usato nella ricostruzione del LCA non riportato come variabile isolata nell'abstract · differenza sulla lassità strumentale statisticamente significativa ma dichiarata dagli stessi autori clinicamente non interpretabile.",perte:"Non è la tua indicazione primaria (tu esegui il LET Lemaire onlay su TUTTI i primari, non solo in revisione), e né il tipo di costrutto (onlay contro altre fissazioni) né l'innesto della ricostruzione del LCA sono specificati nell'abstract — ma è uno dei pochi lavori con esito reale, non solo biomeccanico, a favore dell'aggiunta di un gesto laterale: alimenta T1a dal lato della revisione, non ancora dal lato del tuo costrutto specifico."},{n:2,mono:"m-gray",dot:"orange",sec:"res",j:"Life",h:"La simmetria del quadricipite, non il salto, anticipa la rirottura",v:"Coorte di 48 atleti: un LSI del quadricipite sotto l'85% a fine primo anno si associa a un rischio di rirottura del legamento tre volte più alto entro 24 mesi.",ax:"Kakavas, Malliaropoulos, Forelli",date:"set 2026",meta:"coorte prospettica, 48 atleti, innesto di hamstring · [III]",pmid:'42795410',doi:'10.3390/life16091546',journal:"Life (Basel, Switzerland)",authors:"Kakavas G, Malliaropoulos N, Forelli F",design:"Studio di coorte su atleti dopo ricostruzione primaria unilaterale del LCA con autograft di hamstring; controlli programmati a 6, 9 e 12 mesi con lassità GNRB a 250N, forza isocinetica concentrica del quadricipite (LSI a 60°/s), hop test monopodalico (LSI) ed esiti riferiti dal paziente, un valore per atleta senza conservare la visita di origine; rirottura ipsilaterale confermata alla RM registrata entro 24 mesi dal reinfortunio clinicamente sospettato, senza conservare la data della rirottura.",pop:"48 atleti dopo ricostruzione primaria unilaterale del LCA con innesto di hamstring.",results:"14 rirotture su 48 (29,2%). LSI del quadricipite più basso nel gruppo con rirottura (81,3±7,5% contro 88,1±9,0%; p=0,011); ogni deviazione standard in più di LSI si associa a un rischio di rirottura ridotto (OR 0,43; IC 95% 0,21-0,89). Analisi di soglia esplorativa: LSI del quadricipite <85% associato a una proporzione di rirotture più alta (RR 3,21; IC 95% 1,17-8,82). Le associazioni con lassità strumentale, hop test ed esiti riferiti dal paziente non sono risultate statisticamente robuste.",concl:"Gli autori concludono che la simmetria del quadricipite ha l'associazione più chiara con lo stato di rirottura a 24 mesi, ma dichiarano che l'indisponibilità della visita di origine e della data della rirottura impedisce di stabilire la precedenza temporale, e che la soglia esplorativa dell'85% non va interpretata come una soglia di rientro allo sport validata.",limits:"Precedenza temporale non stabilibile per limiti dichiarati del disegno dei dati (visita di origine e data di rirottura non conservate) · campione piccolo (48 atleti, 14 eventi) · innesto di hamstring, non il tuo tendine quadricipitale/retto femorale.",perte:"Non è il tuo innesto (hamstring, non quadricipite/retto femorale) — ma il segnale, che la simmetria del quadricipite è più informativa del salto o della lassità, va nella stessa direzione dei dati già raccolti sul retto femorale in T3, dove a 6 mesi il deficit estensorio misurato era già rilevante: un'ulteriore ragione per non fermarsi al solo criterio del salto nel colloquio sul rientro."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"The American Journal of Sports Medicine",h:"Nelle lesioni combinate LCA-collaterale mediale l'innesto non-hamstring vince comunque",v:"Registro multicentrico francese, 489 pazienti: gli innesti diversi dall'hamstring danno punteggi IKDC più alti, indipendentemente dallo stato del collaterale mediale.",ax:"Bouguennec, Neri, Carrozzo, Freychet, Hardy, Herce, Kajetanek, Ollivier, Lutz, Cavaignac",date:"set 2026",meta:"coorte di registro multicentrico prospettico, 489 pazienti, IPTW · [III]",pmid:'42801272',doi:'10.1177/03635465261487325',journal:"The American journal of sports medicine",authors:"Bouguennec N, Neri T, Carrozzo A, Freychet B, Hardy A, Herce C, Kajetanek C, Ollivier M, Lutz C, Cavaignac E",design:"Studio di registro multicentrico prospettico (centri della Société Française d'Arthroscopie) su ricostruzione primaria del LCA fra gennaio 2020 e giugno 2022; pazienti categorizzati per stato della lesione mediale (LCA isolato, LCA-collaterale mediale trattato non chirurgicamente, LCA-collaterale mediale trattato chirurgicamente) e tipo di innesto (hamstring contro non-hamstring); ponderazione con probabilità inversa su punteggio di propensione; modelli di regressione multivariabile con termine di interazione innesto×stato del collaterale mediale; esito primario il punteggio soggettivo IKDC.",pop:"722 pazienti eleggibili, 489 (67,7%) con dati completi inclusi nell'analisi primaria.",results:"Gli innesti non-hamstring si associano a punteggi IKDC più alti (β=7,89; IC 95% 3,45-12,33; p<0,001). Le lesioni isolate del LCA hanno punteggi IKDC più alti delle lesioni combinate trattate non chirurgicamente (β=10,41; IC 95% 6,48-14,34; p<0,001). L'interazione innesto×stato del collaterale mediale non è risultata statisticamente significativa (collaterale trattato chirurgicamente: β=-7,02; IC 95% -15,26/1,22; p=0,095): nessuna evidenza che lo stato del collaterale mediale modifichi l'associazione fra tipo di innesto ed esito. Gli innesti non-hamstring si associano anche a un ACL-RSI più alto (β=6,15; IC 95% 0,02-12,28; p=0,049) e a un valore soggettivo del ginocchio più alto (β=8,87; IC 95% 4,53-13,21; p<0,001); nessuna associazione sul livello di attività Tegner.",concl:"Gli autori concludono che gli innesti non-hamstring si associano a punteggi riferiti dal paziente complessivamente più alti, ma non trovano un'evidenza statisticamente significativa che lo stato del collaterale mediale modifichi questa associazione.",limits:"Livello III, coorte di registro non randomizzata · categoria «non-hamstring» aggrega innesti diversi (quadricipite, tendine rotuleo e altri) senza distinguerli nell'abstract · solo il 67,7% dei pazienti eleggibili con dati completi, rischio di selezione.",perte:"Tocca direttamente la tua pratica su due fronti — l'innesto (retto femorale/quadricipite, categorizzato come «non-hamstring» in questo registro) e le lesioni multilegamentose con coinvolgimento del collaterale mediale, che tu ricostruisci con allograft o reinserisci direttamente: un ulteriore segnale di registro a favore della scelta non-hamstring anche quando il collaterale mediale è coinvolto — ma la categoria «non-hamstring» non isola il tendine quadricipitale dagli altri innesti."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"The Knee",h:"Uno slope tibiale differenziale maggiore peggiora gli esiti in revisione del LCA",v:"Coorte di 31 revisioni: quanto più differisce lo slope tibiale mediale-laterale, tanto meno migliorano dolore e qualità di vita dopo la revisione.",ax:"Tsikopoulos, White, Robinson, Kazamias, Duggleby, Hasan, Howells, Murray",date:"set 2026",meta:"coorte retrospettiva monocentrica, 31 pazienti · [IV]",pmid:'42795898',doi:'10.3390/jcm15187125',journal:"Journal of clinical medicine",authors:"Tsikopoulos K, White P, Robinson J, Kazamias K, Duggleby L, Hasan K, Howells N, Murray J",design:"Studio retrospettivo monocentrico su pazienti sottoposti a revisione del LCA fra il 2019 e il 2024; slope tibiale posteriore mediale e laterale misurati indipendentemente da quattro valutatori sulla RM preoperatoria; esito primario la variazione dei sottopunteggi KOOS dal preoperatorio ad almeno un anno dopo l'intervento; correlazione fra la variazione del KOOS e lo slope tibiale posteriore differenziale medio (dPTS) calcolata con il coefficiente di Pearson.",pop:"31 casi di revisione del LCA con dati completi.",results:"Miglioramento postoperatorio statisticamente significativo in tutti e cinque i domini KOOS (Sintomi p=0,036; Dolore p=0,004; Attività quotidiane p=0,002; Sport e tempo libero p<0,001; Qualità di vita p<0,001). Correlazione statisticamente significativa fra lo slope differenziale medio e la variazione del KOOS Sintomi (p=0,007), Dolore (p<0,001), Sport e tempo libero (p=0,034) e Qualità di vita (p=0,010), ma non Attività quotidiane (p=0,070). Affidabilità inter-osservatore da moderata (singolo valutatore) a buona (media dei valutatori) per la misura dello slope differenziale.",concl:"Gli autori concludono che uno slope tibiale posteriore differenziale maggiore si associa a esiti riferiti dal paziente peggiori dopo revisione del LCA, e propongono la misura RM del dPTS come possibile strumento di stratificazione preoperatoria del rischio.",limits:"Livello IV, coorte retrospettiva monocentrica senza gruppo di controllo · campione piccolo (31 pazienti) · correlazione, non un modello aggiustato per i confondenti abituali (età, tipo di innesto, lesioni associate).",perte:"Tu correggi lo slope quando eccessivo nella tua chirurgia di osteotomia; questo lavoro non tratta la correzione chirurgica dello slope ma la sua misura come fattore prognostico in revisione — un argomento in più per misurarlo sistematicamente anche quando la revisione del LCA, non l'osteotomia, è l'intervento pianificato."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Orthopaedics & Traumatology: Surgery & Research",h:"Radice del menisco laterale: stesso esito, radiale o avulsione",v:"65 pazienti operati di LCA con riparazione della radice del menisco laterale: il tipo di lesione non cambia gli esiti funzionali a un follow-up medio di 51 mesi.",ax:"Ancion, Graveleau, Bouguennec",date:"set 2026",meta:"coorte retrospettiva comparativa, 65 pazienti, follow-up medio 51 mesi · [III]",pmid:'42800609',doi:'10.1016/j.otsr.2026.104908',journal:"Orthopaedics & traumatology, surgery & research : OTSR",authors:"Ancion A, Graveleau N, Bouguennec N",design:"Studio retrospettivo comparativo su pazienti sottoposti a ricostruzione del LCA con riparazione associata della radice posteriore del menisco laterale; confronto fra lesioni di tipo avulsione e lesioni radiali; esiti funzionali valutati con IKDC, valore soggettivo del ginocchio, ACL-RSI e punteggio Tegner a un follow-up medio di 51,0 mesi; tassi e livello di rientro allo sport registrati; regressione lineare multivariabile per aggiustare per potenziali fattori confondenti.",pop:"65 pazienti: 31 con lesioni da avulsione, 34 con lesioni radiali.",results:"Nessuna differenza significativa fra i gruppi su IKDC (74,5±14,1 contro 74,0±15,4; p=0,917), valore soggettivo del ginocchio (86,5±13,0 contro 89,0±19,3; p=0,127), ACL-RSI (76,5±24,6 contro 77,7±25,8; p=0,776) o Tegner postoperatorio (6,9±2,5 contro 7,3±2,3; p=0,562). Tassi di rientro allo sport simili (83,9% contro 85,3%; p=1,00), ma fra chi è tornato allo sport la distribuzione del livello di rientro differisce (p=0,026), con una proporzione maggiore di rientro al livello pre-infortunio nel gruppo con lesione radiale. Le analisi multivariabili confermano l'assenza di associazione fra tipo di lesione ed esiti funzionali.",concl:"Gli autori concludono che, a follow-up di medio termine, il tipo di lesione della radice del menisco laterale non influenza gli esiti funzionali riferiti dal paziente dopo ricostruzione del LCA con riparazione associata, ma segnalano una differenza nel livello di rientro allo sport da interpretare con cautela vista la dimensione limitata del campione.",limits:"Livello III, studio retrospettivo · assenza di imaging e valutazione funzionale oggettiva postoperatori · campione limitato per il confronto sul livello di rientro allo sport, dove la differenza osservata va interpretata con cautela.",perte:"È la radice del menisco LATERALE, non la mediale che rifissi di norma con tecnica transtibiale pull-out, e la tecnica di riparazione usata in questo lavoro non è specificata nell'abstract: non trasferibile senza verifica alla tua tecnica esatta — ma conferma, su un follow-up più lungo della media vista finora, che il tipo di lesione della radice pesa meno sull'esito funzionale del previsto."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Clinical Medicine",h:"Il retto femorale isolato come innesto per il LCA: prima revisione narrativa",v:"Revisione narrativa SANRA: dati ancora molto limitati (tre serie cliniche) ma incoraggianti su lunghezza, resistenza e versatilità dell'innesto di solo retto femorale.",ax:"Kolar, Vrgoč, Martinčič",date:"set 2026",meta:"revisione narrativa (SANRA) · [V]",pmid:'42795708',doi:'10.3390/jcm15186935',journal:"Journal of clinical medicine",authors:"Kolar M, Vrgoč G, Martinčič D",design:"Revisione narrativa della letteratura secondo i principi della SANRA (Scale for the Assessment of Narrative Review Articles) sull'innesto isolato di tendine del retto femorale nella ricostruzione del LCA, con sintesi di studi anatomici, biomeccanici, tecnici e clinici su procedure primarie e di revisione.",pop:"Non applicabile — revisione narrativa; l'evidenza clinica sintetizzata consiste in indagini anatomiche e biomeccaniche più tre serie cliniche (una su ricostruzione primaria, due su revisione).",results:"Gli autori riportano proprietà biomeccaniche favorevoli (lunghezza, resistenza e versatilità adeguate dell'innesto) e risultati clinici a breve termine descritti come promettenti nelle tre serie disponibili; l'abstract non riporta valori numerici di esito clinico né intervalli di confidenza per gli studi inclusi.",concl:"Gli autori concludono che l'innesto isolato di retto femorale rappresenta un'opzione emergente promettente per la ricostruzione del LCA, ma che è necessaria un'evidenza prospettica di livello più alto per definirne il ruolo nella chirurgia contemporanea del LCA.",limits:"Revisione narrativa, non sistematica: nessun protocollo PRISMA dichiarato, selezione degli studi non riproducibile · evidenza clinica limitata a tre sole serie cliniche · dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract per nessuno studio incluso.",perte:"È la prima revisione dedicata specificamente al tuo innesto (retto femorale isolato, distinto dal tendine quadricipitale a tutto spessore): utile come mappa della letteratura esistente, ma l'evidenza clinica che sintetizza resta minima — tre serie soltanto — e non aggiunge dati nuovi rispetto a quanto già raccolto in T1a."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of Clinical Medicine",h:"Un profilo RM multidimensionale distingue il LCA infortunato in età pediatrica",v:"462 RM di ginocchio in under-18: un modello di apprendimento automatico su 18 misure ossee distingue i casi di lesione del LCA con un'accuratezza fino al 95,9%.",ax:"Onder, Erbas, Kocaoglu, Colak, Mert, Kurk, Misir",date:"set 2026",meta:"studio caso-controllo retrospettivo, 462 pazienti ≤18 anni, apprendimento automatico · [III]",pmid:'42796019',doi:'10.3390/jcm15187246',journal:"Journal of clinical medicine",authors:"Onder M, Erbas A, Kocaoglu MA, Colak M, Mert M, Kurk MB, Misir A",design:"Studio caso-controllo retrospettivo monocentrico su pazienti di 18 anni o meno sottoposti a RM del ginocchio; diciotto parametri morfometrici femorali e tibiali misurati su RM; sei metodi di selezione delle variabili combinati con sei algoritmi di classificazione (36 combinazioni), valutati con validazione incrociata a 10 fold ripetuta; selezione delle variabili eseguita indipendentemente in ogni fold di addestramento per minimizzare la fuga di informazione.",pop:"462 pazienti ≤18 anni (233 con lesione del LCA, 229 controlli con LCA integro), RM eseguite fra gennaio 2012 e giugno 2025.",results:"13 dei 18 parametri morfometrici differiscono significativamente fra i gruppi dopo correzione per test multipli, inclusi slope tibiale mediale e laterale, profondità tibiale mediale, rapporto del condilo femorale laterale e angoli della fossa intercondiloidea. Area sotto la curva ROC media delle 36 combinazioni di modello: da 0,908 a 0,959; la combinazione migliore (LASSO con naive Bayes) raggiunge un'AUC media di 0,959 (IC 95% 0,905-0,992); LASSO con regressione logistica raggiunge un'AUC di 0,957 con buona calibrazione (Brier score 0,080).",concl:"Gli autori concludono che la lesione pediatrica del LCA si associa a un profilo morfometrico multidimensionale RM distinto sia a livello femorale sia tibiale, con alta capacità discriminante dei modelli di apprendimento automatico, ma precisano che i modelli vanno interpretati come classificatori dello stato di lesione già accertato, non come predittori prospettici di un infortunio futuro.",limits:"Studio caso-controllo retrospettivo monocentrico: non può stabilire se le differenze morfometriche precedano o seguano la lesione · nessuna validazione esterna su una coorte indipendente · i modelli classificano una lesione già avvenuta, non predicono il rischio futuro, come dichiarato esplicitamente dagli stessi autori.",perte:"Il LCA nel paziente scheletricamente immaturo o in transizione è dentro il tuo perimetro dai 14 anni in su: questo lavoro non cambia l'indicazione chirurgica né la tecnica, ma offre un profilo morfometrico riproducibile che potrebbe un giorno affiancare la sola età ossea nella valutazione del rischio — oggi resta uno strumento di classificazione retrospettiva, non di screening prospettico."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Diagnostics",h:"A 24 mesi l'asimmetria eccentrica degli hamstring si dimezza, ma non sparisce",v:"Confronto trasversale fra due coorti indipendenti di 30 atleti: l'asimmetria di forza eccentrica degli hamstring scende dal 70% al 23% di atleti sotto soglia fra 12 e 24 mesi, ma resta in uno su quattro.",ax:"Kakavas, Malliaropoulos, Prill, Forelli",date:"set 2026",meta:"studio trasversale comparativo, 60 atleti (due coorti indipendenti da 30), monocentrico · [IV]",pmid:'42793826',doi:'10.3390/diagnostics16183042',journal:"Diagnostics (Basel, Switzerland)",authors:"Kakavas G, Malliaropoulos N, Prill R, Forelli F",design:"Studio trasversale comparativo monocentrico su atleti maschi valutati una sola volta, in una coorte indipendente a 12 mesi o in una a 24 mesi dopo ricostruzione primaria unilaterale del LCA con innesto di hamstring; forza eccentrica di picco e media durante l'esercizio nordico degli ischiocrurali misurata con dispositivo NordBord a 50 Hz; esito primario l'indice di simmetria degli arti (LSI) sulla forza di picco.",pop:"60 atleti maschi: 30 nella coorte indipendente a 12 mesi, 30 nella coorte indipendente a 24 mesi.",results:"LSI della forza di picco 84,6±9,3% nella coorte a 12 mesi contro 93,5±6,8% nella coorte a 24 mesi (differenza media 8,9 punti percentuali; IC 95% 4,7-13,1; p<0,001; d=1,09). La forza di picco dell'arto operato è maggiore di 32,5N nella coorte a 24 mesi (IC 95% 6,8-58,2; p=0,014), mentre l'arto sano non differisce fra le coorti (differenza 2,5N; IC 95% -21,9/26,9; p=0,838). LSI della forza di picco sotto il 90% in 21 atleti su 30 (70,0%; IC 95% 52,1-83,3%) a 12 mesi contro 7 su 30 (23,3%; IC 95% 11,8-40,9%) a 24 mesi (χ²; p<0,001).",concl:"Gli autori concludono che la minore asimmetria eccentrica osservata nella coorte indipendente a 24 mesi è dovuta soprattutto a un aumento della forza dell'arto operato, non a una variazione dell'arto sano, ma che quasi un quarto degli atleti a 24 mesi resta sotto la soglia del 90% di LSI: il solo tempo trascorso dall'intervento non sostituisce una valutazione oggettiva tardiva della forza eccentrica dei flessori del ginocchio.",limits:"Disegno trasversale fra coorti indipendenti, non longitudinale sugli stessi atleti: non misura il decorso individuale · monocentrico, soli atleti maschi · innesto di hamstring, non il tuo tendine quadricipitale/retto femorale, e nessun rinforzo laterale dichiarato nella coorte.",perte:"Non è il tuo innesto né la tua tecnica (hamstring, nessun LET dichiarato) — ma il messaggio di fondo, che il tempo da solo non garantisce il recupero della forza, converge con i dati già raccolti in T3 sul deficit estensorio persistente a 6 mesi sul retto femorale, questa volta dal lato della forza flessoria e a un orizzonte più lungo."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"Medicina",h:"Le fratture periprotesiche di ginocchio restano una sfida, ma trattabili",v:"56 pazienti trattati per frattura periprotesica dopo protesi di ginocchio: successo terapeutico nell'81% dei casi, quasi sempre con trattamento chirurgico.",ax:"Sypień, Jaglarz, Gralewski, Tramś, Bołtuć, Kamiński, Grzelecki",date:"set 2026",meta:"studio bicentrico retrospettivo con revisione sistematica della letteratura, 56 pazienti · [IV]",pmid:'42796334',doi:'10.3390/medicina62091727',journal:"Medicina (Kaunas, Lithuania)",authors:"Sypień P, Jaglarz D, Gralewski J, Tramś E, Bołtuć W, Kamiński R, Grzelecki D",design:"Analisi retrospettiva bicentrica di pazienti trattati per frattura periprotesica dopo protesi totale di ginocchio, con revisione del protocollo chirurgico, dei tempi di trattamento e del tasso di complicanze; risultati confrontati con la letteratura disponibile tramite revisione sistematica.",pop:"56 pazienti con frattura periprotesica dopo protesi totale di ginocchio.",results:"Il 91% dei pazienti è stato trattato chirurgicamente (revisione della protesi o osteosintesi); successo terapeutico nell'81% dei casi complessivi. Nella revisione protesica la sostituzione della componente femorale con un impianto semi-vincolato è stata la scelta più frequente; nelle fratture periprotesiche femorali, la destabilizzazione della fissazione si è osservata soprattutto nel tipo II della classificazione di Lewis-Rorabeck.",concl:"Gli autori concludono che, nonostante la complessità del problema, il trattamento delle fratture periprotesiche di ginocchio può essere efficace: l'osteosintesi è una buona opzione quando l'impianto resta stabile, mentre nella revisione protesica si tende a impianti con maggior grado di vincolo per garantire la stabilità articolare.",limits:"Studio retrospettivo bicentrico, non comparativo randomizzato · campione piccolo (56 pazienti) per un esito complesso come la frattura periprotesica · criteri di successo terapeutico non dettagliati numericamente nell'abstract oltre alla percentuale complessiva.",perte:"Non riguarda la componente robotica VELYS ma una complicanza che può capitare a qualunque protesi totale di ginocchio: un promemoria sul trattamento — osteosintesi se l'impianto è stabile, revisione con impianto più vincolato se non lo è — più che un dato che cambia la tua tecnica d'impianto."}];
var SUGGQ=[{"k": "kol","n": "Francisco Endara Urresta","w": "Clínica Arthros, Quito, Ecuador — ultimo autore della scheda 1 di oggi sul rinforzo laterale e la sopravvivenza dell'innesto dopo revisione del LCA; corrispondenza tecnica diretta con il tuo rinforzo laterale sistematico, rete chirurgica argentino-ecuadoriana non ancora rappresentata nei tuoi riferimenti. Sostituisce Jiangtao Dong (27 settembre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Il lavoro del giorno arriva dall'Argentina e dall'Ecuador: in trecento revisioni del legamento crociato anteriore, aggiungere un rinforzo laterale — tenodesi extra-articolare o ricostruzione del legamento antero-laterale — alla sola revisione alza la sopravvivenza dell'innesto a cinque anni dal 79,9 al 90,6 per cento, e dimezza il pivot shift residuo. Lo studio non è randomizzato, e non dice se sia meglio la tenodesi o la ricostruzione antero-laterale: il confronto diretto fra le due non è conclusivo. Lo stesso giorno un registro francese su quasi cinquecento pazienti conferma che gli innesti diversi dall'hamstring danno punteggi funzionali più alti anche quando è coinvolto il legamento collaterale mediale. Due reti diverse, la stessa direzione: innesto non-hamstring e rinforzo laterale continuano a convergere, senza però isolare ancora la tua combinazione esatta di tendine quadricipitale e Lemaire onlay.\n\nSul criterio di rientro allo sport, due lavori dello stesso gruppo greco vanno nella stessa direzione di quanto già sai sul tuo innesto: la simmetria di forza del quadricipite a un anno predice meglio la rirottura a due anni del salto monopodalico o della lassità misurata in ambulatorio, e l'asimmetria di forza dei flessori si riduce col tempo ma resta presente in circa un quarto degli atleti anche a due anni. Il tempo da solo non basta.\n\nLe altre schede di oggi: uno slope tibiale differenziale maggiore peggiora gli esiti in revisione del legamento crociato; il tipo di lesione della radice del menisco laterale — radiale o da avulsione — non cambia l'esito funzionale a oltre quattro anni dalla ricostruzione del crociato, anche se sembra influenzare il livello di rientro sportivo; è uscita la prima revisione dedicata al tuo innesto, il retto femorale isolato, ancora con pochissimi dati clinici; un profilo di risonanza magnetica multidimensionale distingue il legamento crociato leso in età pediatrica; e una casistica di fratture periprotesiche di ginocchio conferma un tasso di successo dell'81 per cento con trattamento chirurgico mirato.\n\nNessun richiamo nuovo: i due richiami del nucleo sorvegliato, Zimmer Biomet e DePuy Synthes, restano aperti, invariati. Nessuna ritrattazione nuova sul citato. Nessuna linea guida davvero nuova nella finestra dei sessanta giorni.";
var BRIEF_DIALOGO=[{"chi": "A","t": "Il lavoro di oggi arriva da Argentina ed Ecuador: in trecento revisioni del crociato, aggiungere un rinforzo laterale porta la sopravvivenza dell'innesto a cinque anni dal 79,9 al 90,6 per cento."},{"chi": "B","t": "Quindi conferma quello che fai sempre sui primari — il rinforzo laterale aiuta. Ma qui parliamo di revisioni, giusto?"},{"chi": "A","t": "Esatto, è revisione, non ricostruzione primaria. E lo studio non dice se conviene di più la tenodesi o la ricostruzione del legamento antero-laterale: il confronto diretto fra le due non è conclusivo, troppo pochi eventi."},{"chi": "B","t": "E per il tuo tendine quadricipitale? Lo studio lo isola?"},{"chi": "A","t": "No, il tipo di innesto della ricostruzione non è riportato separatamente. Però lo stesso giorno un registro francese su quasi cinquecento pazienti mostra che gli innesti diversi dall'hamstring danno risultati migliori, anche quando è coinvolto il legamento collaterale mediale."},{"chi": "B","t": "Due reti diverse, la stessa direzione, ma nessuna delle due arriva alla tua combinazione esatta."},{"chi": "A","t": "Esatto. Poi c'è il tema del rientro allo sport: due lavori dello stesso gruppo greco mostrano che la simmetria di forza del quadricipite a un anno predice la rirottura meglio del salto monopodalico."},{"chi": "B","t": "E questo, per te che segui già la simmetria di forza, che cosa cambia?"},{"chi": "A","t": "Rafforza quello che le tensioni del sistema dicono da mesi: la sola misura, fatta una volta, non basta. Il secondo lavoro dello stesso gruppo mostra che l'asimmetria dei flessori si riduce col tempo, ma resta in un atleta su quattro anche a due anni."},{"chi": "B","t": "Quindi per la tua VELYS, oggi non c'è nulla sulla protesi robotica?"},{"chi": "A","t": "No, ma c'è una casistica di fratture periprotesiche di ginocchio, ottantuno per cento di successo con trattamento chirurgico mirato — utile a prescindere dalla tecnica di impianto."},{"chi": "B","t": "E sul fronte richiami e ritrattazioni?"},{"chi": "A","t": "Tutto fermo: i due richiami noti restano aperti, nessuna ritrattazione nuova, nessuna linea guida davvero nuova questa settimana."}];
